#!/bin/bash
# Builds CryptoExpo.app, Release, unsigned: build-sim/ (arm64 simulator) and build/ (device; sign it with
# ../../heavy-list/probe/resign.sh before installing). DEVICE_ONLY=1 skips the simulator. ios/ is generated by expo prebuild.
set -euo pipefail
cd "$(dirname "$0")"
H=$(pwd)
export LANG=${LANG:-en_US.UTF-8}
../prepare.sh
npm ci
CI=1 npx expo prebuild --platform ios   # runs pod install
DD=$H/build/derived; mkdir -p "$DD"
xb() { # $1 = sdk, $2 = destination, $3 = derived data dir
  (cd ios && xcodebuild -workspace CryptoExpo.xcworkspace -scheme CryptoExpo -configuration Release \
    -sdk "$1" -destination "$2" -derivedDataPath "$3" CODE_SIGNING_ALLOWED=NO build)
}
if [ "${DEVICE_ONLY:-0}" != 1 ]; then
  xb iphonesimulator "generic/platform=iOS Simulator" "$DD/sim" > build/build-sim.log 2>&1 || { echo "simulator build failed (build/build-sim.log)"; exit 1; }
  rm -rf build-sim/CryptoExpo.app; mkdir -p build-sim
  cp -R "$DD/sim/Build/Products/Release-iphonesimulator/CryptoExpo.app" build-sim/
fi
xb iphoneos "generic/platform=iOS" "$DD/device" > build/build-device.log 2>&1 || { echo "device build failed (build/build-device.log)"; exit 1; }
rm -rf build/CryptoExpo.app
cp -R "$DD/device/Build/Products/Release-iphoneos/CryptoExpo.app" build/
echo built
